async (page) => {
  const { exec } = require('child_process');

  // Count how many playwright artifact directories we have
  exec('ls -d /tmp/playwright* 2>/dev/null | wc -l', (error, stdout, stderr) => {
    if (error) {
      console.log('No playwright directories found or unable to count');
      return;
    }
    const count = parseInt(stdout.trim());
    console.log(`Found ${count} playwright artifact directories`);

    // Remove the playwright artifacts directories
    exec('rm -rf /tmp/playwright-artifacts-* /tmp/playwright_chromiumdev_profile-* 2>/dev/null', (error, stdout, stderr) => {
      if (error) {
        console.error(`Error removing directories: ${error}`);
        return;
      }
      console.log('Successfully removed playwright artifacts directories');
    });
  });
}
